{
  "interpretation": {
    "name": "TightenForkliftFastenersLine2AndReturnTool",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Bring the shared nutrunner NR7 to station st2, tighten the fasteners of variant F30, and send the tool back to the crib immediately afterwards, while the evaluation and recording run during the return trip.",
    "constraints": [
      "NR7 is reserved before any use and the reservation is released only after the tool is back at the crib",
      "transport-tool to the station completes before configure-tool and tighten-fasteners",
      "the tightening program comes only from get-program for variant F30; no numeric process values appear in the Recipe",
      "the return transport starts right after tighten-fasteners completes",
      "the tightening is evaluated against its program and recorded for traceability (parallel to the return transport)",
      "transport-tool is delegated to the Executor agvexecutor",
      "every tool-using Step depends on reserve-tool so that it renews the lease"
    ],
    "preference": "Minimise the time the tool is held at the station by starting the return transport immediately after tightening.",
    "priority": "normal",
    "horizon": "single execution for the current request",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-tighten-and-return-nr7",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "deliver",
        "steps": [
          {
            "name": "reserve",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "deliver",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "finish",
        "steps": [
          {
            "name": "configure",
            "service": "configure-tool",
            "next": ["tighten-fasteners"],
            "dep": ["program", "reserve", "transport-to-station"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-fasteners",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure", "reserve"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "finish",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": ["release"],
            "dep": ["reserve", "tighten-fasteners"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "evaluate",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-fasteners", "program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-fasteners"],
            "executor": null,
            "params": {}
          },
          {
            "name": "release",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
